 "content": "def transform(grid):
    """Fill gaps between aligned foreground cells with color 2."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    from collections import Counter

    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    foreground = {value for row in grid for value in row if value != background}
    result = [row[:] for row in grid]

    for color in foreground:
        for r, row in enumerate(grid):
            cols = [c for c, value in enumerate(row) if value == color]
            if len(cols) >= 2:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == background:
                        result[r][c] = 2

        for c in range(len(grid[0])):
            rows = [r for r in range(len(grid)) if grid[r][c] == color]
            if len(rows) >= 2:
                for r in range(min(rows), max(rows) + 1):
                    if grid[r][c] == background:
                        result[r][c] = 2

    return result
