 "content": "def transform(grid):
    """Fill qualifying horizontal/vertical marker lines with color 2.

    A line qualifies when it contains at least three original foreground
    markers. Fill across the foreground bounding box, preserving all existing
    cells and using the original grid to decide which lines qualify.
    """
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    height, width = len(grid), len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("grid must be rectangular")

    from collections import Counter

    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    points = [
        (r, c)
        for r in range(height)
        for c in range(width)
        if grid[r][c] != background
    ]
    if not points:
        return [row[:] for row in grid]

    top = min(r for r, _ in points)
    bottom = max(r for r, _ in points)
    left = min(c for _, c in points)
    right = max(c for _, c in points)
    out = [row[:] for row in grid]

    # Count markers from the unmodified input, then extend each qualifying
    # line over the complete bounding box of the marker pattern.
    for r in range(top, bottom + 1):
        if sum(grid[r][c] != background for c in range(left, right + 1)) >= 3:
            for c in range(left, right + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    for c in range(left, right + 1):
        if sum(grid[r][c] != background for r in range(top, bottom + 1)) >= 3:
            for r in range(top, bottom + 1):
                if grid[r][c] == background:
                    out[r][c] = 2

    return out
