        return out
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)

    # Complete the bounding top and bottom rows only when at least two
    # original markers lie on that row.
    for r in {r0, r1}:
        cols = [c for c in range(w) if grid[r][c] != bg]
