        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Interior lines are filled only with at least three original markers.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(w) if grid[r][c] != bg]
        if len(cols) >= 3:
            for c in range(cols[0], cols[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(c0 + 1, c1):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
